/**
 * Run a probe that answers 「is this degraded」, treating a THROW as degraded.
 *
 * Fail-closed on purpose: if the probe itself cannot run, the honest reading is 「we do not know, and a
 * number that might be wrong must say so」. The one exception is `editorAvailable`, whose throwing means
 * the service is missing — which is also degraded, so the default is the same and is stated at the call
 * site rather than hidden here.
 */
export function safeFlag(probe               , onThrow = true)          {
  try {
    return probe() === true
  } catch {
    return onThrow
  }
}

/**
 * Can the task graph be READ? — answering the question `readGraph` deliberately cannot.
 *
 * `readGraph` swallows every read and parse failure and returns `emptyGraph`, so 「could not read」 and
 * 「no plan yet」 arrive as the same value. That collapse is right for its callers (a card must render
 * something) and wrong for THIS one: `v317 ③` insists the two are different claims — an absent file is a
 * healthy project that never made a plan, while an unreadable or unparseable one must say so.
 *
 * `readText` and `exists` are injected so this module stays IO-free and testable by shape.
 */
export function graphIsUnreadable(
  readText              ,
  isAbsent                             ,
  parse                           ,
)          {
  let text        
  try {
    text = readText()
  } catch (error) {
    return !isAbsent(error)
  }
  try {
    parse(text)
    return false
  } catch {
    return true
  }
}

export function describeDegradation(input                   )                    {
  const reasons           = []
  if (input.graphUnreadable) {
    reasons.push('任务图读不出来：卡片上的 0 可能是「没读成」而不是「没有计划」')
  }
  if (input.ledgerDeferred) {
    reasons.push('台账本轮被拒读（半条记录）：计数可能偏小')
  }
  if (!input.editorAvailable) {
    reasons.push('configEditor 服务不可用：下面的开关显示的是插件默认值，点击不会落盘')
  }
  if (reasons.length === 0) return { degraded: false }
  return { degraded: true, degradedReason: reasons.join('；') }
}
